    val MAP: Map<String, DuaText> = mapOf(
        "dua_evening_witness" to DuaText("തൌഹീദിൻ്റെ സായാഹ്ന സാക്ഷി", "അല്ലാഹുവേ, നീ അല്ലാഹുവാകുന്നു എന്നും നീയല്ലാതെ ഒരു ദൈവവുമില്ലെന്നും, പങ്കാളിയില്ലാത്തവനും, മുഹമ്മദ് സൽമാൻ നിൻറെ ദാസനും ദൂതനും ആണെന്നും സാക്ഷ്യം വഹിക്കാൻ നിൻറെ സിംഹാസനവാഹകൻമാരെയും മലക്കുകളേയും നിൻറെ സകല സൃഷ്ടികളെയും ഞാൻ വൈകുന്നേരം വിളിച്ചുകൊണ്ടിരിക്കുന്നു.", "വൈകുന്നേരം നാല് തവണ പറഞ്ഞതായി വിവരണത്തിൽ പരാമർശിക്കുന്നു.", "വൈകുന്നേരം നാല് തവണ പറഞ്ഞതായി വിവരണത്തിൽ പരാമർശിക്കുന്നു."),
        "dua_morning_blessing" to DuaText("അനുഗ്രഹങ്ങൾക്ക് പ്രഭാത നന്ദി", "അല്ലാഹുവേ, എനിക്കോ നിൻറെ സൃഷ്ടികളിലോ ഇന്ന് രാവിലെ ലഭിച്ച ഏത് അനുഗ്രഹവും നിന്നിൽ നിന്നുള്ളതാണ്, പങ്കാളിയില്ലാതെ; അതിനാൽ എല്ലാ സ്തുതിയും നന്ദിയും നിനക്കുള്ളതാണ്.", "അല്ലാഹുവിൻറെ അനുഗ്രഹങ്ങൾക്ക് നന്ദിയുടെ പ്രഭാത ധിക്കർ.", "അല്ലാഹുവിൻറെ അനുഗ്രഹങ്ങൾക്ക് നന്ദിയുടെ പ്രഭാത ധിക്കർ."),
        "dua_evening_blessing" to DuaText("സായാഹ്നം അനുഗ്രഹങ്ങൾക്ക് നന്ദി", "അല്ലാഹുവേ, എനിക്കോ നിൻറെ സൃഷ്ടികളിലോ ഇന്ന് വൈകുന്നേരം ലഭിച്ച ഏത് അനുഗ്രഹവും നിന്നിൽ നിന്നുള്ളതാണ്, പങ്കാളിയില്ലാതെ; അതിനാൽ എല്ലാ സ്തുതിയും നന്ദിയും നിനക്കുള്ളതാണ്.", "അല്ലാഹുവിൻറെ അനുഗ്രഹങ്ങൾക്ക് നന്ദിയുടെ സായാഹ്ന ധിക്കർ.", "അല്ലാഹുവിൻറെ അനുഗ്രഹങ്ങൾക്ക് നന്ദിയുടെ സായാഹ്ന ധിക്കർ."),
